const audioPlayerSlot=document.getElementById("audioPlayerSlot"),audioPlayer=document.getElementById("audioPlayer");function updateAudioHeight(){if(audioPlayer.classList.contains("is-fixed")){const e=audioPlayer.getBoundingClientRect().height;document.documentElement.style.setProperty("--audio-height",`${e}px`)}else document.documentElement.style.setProperty("--audio-height","0px")}const intersectionObserver=new IntersectionObserver(([e])=>{audioPlayer.classList.toggle("is-fixed",!e.isIntersecting),requestAnimationFrame(updateAudioHeight)},{threshold:0}),resizeObserver=new ResizeObserver(()=>{updateAudioHeight()});intersectionObserver.observe(audioPlayerSlot),resizeObserver.observe(audioPlayer),window.addEventListener("resize",updateAudioHeight),window.addEventListener("orientationchange",updateAudioHeight);